Widget brand([double s=70])=>SvgPicture.asset('logo.svg',width:s,height:s);

class Login extends StatefulWidget{const Login({super.key,required this.onTheme});final ValueChanged<bool> onTheme;@override State<Login> createState()=>_LoginState();}
class _LoginState extends State<Login>{final user=TextEditingController(),pass=TextEditingController();String err='';void enter(){if((user.text.trim()=='admin'||user.text.trim()=='mojtaba')&&pass.text=='1234'){Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>Shell(onTheme:widget.onTheme)));}else{setState(()=>err='نام کاربری یا رمز عبور اشتباه است');}}@override Widget build(BuildContext c)=>Scaffold(body:Container(decoration:const BoxDecoration(gradient:LinearGradient(colors:[navy,navy2,Color(0xfff4f6f8)],begin:Alignment.topCenter,end:Alignment.bottomCenter)),child:Center(child:Card(child:Padding(padding:const EdgeInsets.all(28),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Column(mainAxisSize:MainAxisSize.min,children:[brand(95),const Text('میراث ملک',style:TextStyle(fontSize:30,fontWeight:FontWeight.bold)),const Text('سیستم مدیریت هوشمند دپارتمان املاک'),const Text('مدیریت مهندس مجتبی صفری',style:TextStyle(color:gold,fontWeight:FontWeight.bold)),const Text('مدیر فروش خانم طهماسبی پور'),const SizedBox(height:20),TextField(controller:user,decoration:const InputDecoration(labelText:'نام کاربری',border:OutlineInputBorder())),const SizedBox(height:10),TextField(controller:pass,obscureText:true,onSubmitted:(_)=>enter(),decoration:const InputDecoration(labelText:'رمز عبور',border:OutlineInputBorder())),if(err.isNotEmpty)Text(err,style:const TextStyle(color:Colors.red)),const SizedBox(height:16),SizedBox(width:double.infinity,height:50,child:FilledButton(onPressed:enter,child:const Text('ورود'))),const Text('ورود اولیه: admin / 1234',style:TextStyle(fontSize:11))]))))));}
