class Home extends StatelessWidget{const Home({super.key,required this.onTab});final ValueChanged<int> onTab;@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(18),children:[Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(borderRadius:BorderRadius.circular(22),gradient:const LinearGradient(colors:[navy,navy2])),child:const Text('مدیریت هوشمند دپارتمان املاک\nمدیریت مهندس مجتبی صفری',style:TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.bold))),const SizedBox(height:15),GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:MediaQuery.sizeOf(c).width>700?3:2,children:[Tile('ثبت فایل جدید',Icons.add_home_work,Colors.green,()=>showDialog(context:c,builder:(_)=>const AddFile())),Tile('فایل‌ها',Icons.list,Colors.blue,()=>onTab(1)),Tile('مشتریان',Icons.people,Colors.deepPurple,()=>onTab(2)),Tile('جلسات',Icons.event,Colors.orange,()=>onTab(3)),Tile('کمیسیون',Icons.calculate,Colors.teal,()=>onTab(4)),Tile('کاربران',Icons.groups,Colors.blueGrey,()=>showDialog(context:c,builder:(_)=>const Users()))])]);}
class Tile extends StatelessWidget{const Tile(this.t,this.i,this.col,this.tap,{super.key});final String t;final IconData i;final Color col;final VoidCallback tap;@override Widget build(BuildContext c)=>Card(color:col,child:InkWell(onTap:tap,child:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(i,color:Colors.white,size:35),Text(t,style:const TextStyle(color:Colors.white,fontWeight:FontWeight.bold))]))));}

class Store{static const key='properties';static Future<List<Map<String,dynamic>>> get()async{final p=await SharedPreferences.getInstance();final s=p.getString(key);if(s==null)return[];return (jsonDecode(s) as List).map((e)=>Map<String,dynamic>.from(e)).toList();}static Future<void> put(List<Map<String,dynamic>> a)async{final p=await SharedPreferences.getInstance();await p.setString(key,jsonEncode(a));}static Future<String> code()async{final a=await get();return'MM-${(a.length+1).toString().padLeft(6,'0')}';}static Future<void> add(Map<String,dynamic> x)async{final a=await get();a.add(x);await put(a);}}

class Files extends StatefulWidget{const Files({super.key});@override State<Files> createState()=>_FilesState();}
class _FilesState extends State<Files>{List<Map<String,dynamic>> a=[];@override void initState(){super.initState();load();}Future<void> load()async{final x=await Store.get();if(mounted)setState(()=>a=x);}Future<void> add()async{await showDialog(context:context,builder:(_)=>const AddFile());await load();}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[Row(children:[const Expanded(child:Text('فایل‌های املاک',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold))),FilledButton.icon(onPressed:add,icon:const Icon(Icons.add),label:const Text('ثبت فایل'))]),const SizedBox(height:10),if(a.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(25),child:Center(child:Text('هنوز فایلی ثبت نشده است')))),...a.reversed.map((x)=>Card(child:ListTile(title:Text('${x['code']} • ${x['title']}'),subtitle:Text('${x['type']} • ${x['area']} متر\nمالک: ${x['owner']}\n${x['address']}'),trailing:PopupMenuButton<String>(onSelected:(v)async{final l=(x['divar']??'').toString();if(v=='copy')await Clipboard.setData(ClipboardData(text:l));if(v=='open'&&l.isNotEmpty)await launchUrl(Uri.parse(l),mode:LaunchMode.externalApplication);},itemBuilder:(_)=>const[PopupMenuItem(value:'copy',child:Text('کپی لینک دیوار')),PopupMenuItem(value:'open',child:Text('باز کردن لینک دیوار'))]))))]);}

class AddFile extends StatefulWidget{const AddFile({super.key});@override State<AddFile> createState()=>_AddFileState();}
class _AddFileState extends State<AddFile>{final form=GlobalKey<FormState>();final x=<String,TextEditingController>{};String type='آپارتمان',deal='فروش';final checks=<String,bool>{};bool busy=false;final items=['سند مالکیت دیده شد','هویت مالک احراز شد','شماره مالک تأیید شد','آدرس بررسی شد','قیمت قطعی شد','پارکینگ','انباری','آسانسور','بالکن','بازسازی','نورگیر','سند تک‌برگ','پایان‌کار','عدم خلاف','فوری','قابل تخفیف','معاوضه','سرمایه‌گذاری','فایل اختصاصی دفتر'];@override void initState(){super.initState();for(final k in ['title','area','rooms','year','floor','unit','price','deposit','rent','owner','phone','national','address','postal','document','permit','consultant','divar','description']){x[k]=TextEditingController();checks[k]=false;}for(final k in items){checks[k]=false;}}@override void dispose(){for(final v in x.values)v.dispose();super.dispose();}Widget f(String k,String label,{bool req=false})=>Padding(padding:const EdgeInsets.only(bottom:9),child:TextFormField(controller:x[k],decoration:InputDecoration(labelText:label,border:const OutlineInputBorder()),validator:req?(v)=>v==null||v.trim().isEmpty?'الزامی است':null:null));Future<void> paste()async{final d=await Clipboard.getData(Clipboard.kTextPlain);if(d?.text!=null)setState(()=>x['divar']!.text=d!.text!);}Future<void> save()async{if(!form.currentState!.validate())return;setState(()=>busy=true);final code=await Store.code();final m=<String,dynamic>{'code':code,'type':type,'deal':deal,'saved':DateTime.now().toIso8601String(),'checks':checks};for(final e in x.entries)m[e.key]=e.value.text.trim();await Store.add(m);if(mounted){Navigator.pop(context);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('فایل $code ذخیره شد')));}}@override Widget build(BuildContext c)=>AlertDialog(title:const Text('ثبت فایل کامل'),content:SizedBox(width:720,child:Form(key:form,child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('کد فایل خودکار است',style:TextStyle(color:gold,fontWeight:FontWeight.bold)),DropdownButtonFormField<String>(initialValue:type,decoration:const InputDecoration(labelText:'نوع ملک',border:OutlineInputBorder()),items:const['آپارتمان','ویلا','تجاری','اداری','زمین','باغ','مشارکت ساخت','پیش‌فروش'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>type=v!)),DropdownButtonFormField<String>(initialValue:deal,decoration:const InputDecoration(labelText:'نوع معامله',border:OutlineInputBorder()),items:const['فروش','رهن و اجاره','اجاره','پیش‌فروش','مشارکت'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>deal=v!)),f('title','عنوان فایل',req:true),f('area','متراژ'),f('rooms','تعداد خواب'),f('year','سال ساخت'),f('floor','طبقه'),f('unit','واحد'),f('price','قیمت فروش'),f('deposit','رهن'),f('rent','اجاره'),f('owner','نام مالک',req:true),f('phone','شماره مالک',req:true),f('national','کد ملی مالک'),f('address','آدرس کامل',req:true),f('postal','کد پستی'),f('document','شماره سند'),f('permit','جواز/پایان‌کار'),f('consultant','مشاور مسئول'),Container(padding:const EdgeInsets.all(8),decoration:BoxDecoration(border:Border.all(color:Colors.grey),borderRadius:BorderRadius.circular(10)),child:Column(children:[TextField(controller:x['divar'],decoration:InputDecoration(labelText:'لینک آگهی دیوار',border:const OutlineInputBorder(),suffixIcon:IconButton(onPressed:paste,icon:const Icon(Icons.content_paste)))),Row(children:[TextButton.icon(onPressed:paste,icon:const Icon(Icons.content_paste),label:const Text('Paste')),TextButton.icon(onPressed:()=>Clipboard.setData(ClipboardData(text:x['divar']!.text)),icon:const Icon(Icons.copy),label:const Text('کپی'))])])),f('description','توضیحات'),const SizedBox(height:8),const Text('چک‌لیست فایل',style:TextStyle(fontWeight:FontWeight.bold)),...items.map((q)=>CheckboxListTile(value:checks[q],onChanged:(v)=>setState(()=>checks[q]=v??false),title:Text(q),dense:true))])))),actions:[TextButton(onPressed:busy?null:()=>Navigator.pop(c),child:const Text('انصراف')),FilledButton.icon(onPressed:busy?null:save,icon:const Icon(Icons.save),label:const Text('ثبت و ذخیره'))]);}}

